import java.io.*;
import java.util.*;

public class P1575D {
    public static void main(String[] args) throws IOException {
        InputStreamReader isr = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(isr);
        PrintWriter pw = new PrintWriter(System.out);

        String line = br.readLine();
        char[] s = line.toCharArray();
        int result = 0;

        if (s.length == 1) {
            if (s[0] == '0' || s[0] == '_' || s[0] == 'X') {
                result = 1;
            }
        } else {
            int len = s.length;
            if (!(s[len - 1] == 'X' && s[len - 2] == 'X')) {
                if (canPlace(s, len - 1, '5') && canPlace(s, len - 2, '2')) {
                    char[] temp = Arrays.copyOf(s, len);
                    assign(temp, len - 1, '5');
                    assign(temp, len - 2, '2');
                    result += countOptions(temp);
                }
                if (canPlace(s, len - 1, '0') && canPlace(s, len - 2, '5')) {
                    char[] temp = Arrays.copyOf(s, len);
                    assign(temp, len - 1, '0');
                    assign(temp, len - 2, '5');
                    result += countOptions(temp);
                }
                if (canPlace(s, len - 1, '5') && canPlace(s, len - 2, '7')) {
                    char[] temp = Arrays.copyOf(s, len);
                    assign(temp, len - 1, '5');
                    assign(temp, len - 2, '7');
                    result += countOptions(temp);
                }
            }
            if (s[len - 1] == 'X' && s[len - 2] == 'X') {
                char[] temp = Arrays.copyOf(s, len);
                assign(temp, len - 1, '0');
                result += countOptions(temp);
            } else if (canPlace(s, len - 1, '0') && canPlace(s, len - 2, '0')) {
                char[] temp = Arrays.copyOf(s, len);
                assign(temp, len - 1, '0');
                assign(temp, len - 2, '0');
                result += countOptions(temp);
            }
        }
        pw.println(result);
        pw.flush();
    }

    private static boolean canPlace(char[] s, int index, char d) {
        return s[index] == 'X' || s[index] == '_' || s[index] == d;
    }

    private static void assign(char[] s, int index, char d) {
        if (s[index] == 'X') {
            fill(s, d);
        } else {
            s[index] = d;
        }
    }

    private static void fill(char[] s, char d) {
        for (int i = 0; i < s.length; i++) {
            if (s[i] == 'X') {
                s[i] = d;
            }
        }
    }

    private static int countOptions(char[] s) {
        int options = 1;
        if (s[0] == '0') {
            return 0;
        }
        if (s[0] == '_') {
            options *= 9;
        } else if (s[0] == 'X') {
            options *= 9;
            fill(s, '1');
        }
        for (int i = 1; i < s.length; i++) {
            if (s[i] == '_') {
                options *= 10;
            } else if (s[i] == 'X') {
                options *= 10;
                fill(s, '1');
            }
        }
        return options;
    }
}
